import{genres,catalog,rome,selectTracks,score,eligibility,canVote,rankRows}from'./core.js';
const $=s=>document.querySelector(s),KEY='vibepulse-v1';const escape=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let state;try{state=JSON.parse(localStorage.getItem(KEY))}catch{}state=state||{uid:crypto.randomUUID(),name:'',prefs:['Indie','Pop','Elettronica'],connected:false,onboard:false,rounds:{},saved:[],applications:[]};
let route=location.hash.slice(1)||'daily',step=0,pendingPrefs=[...state.prefs],demoReveal=false,period='day',filter='Tutti',active=null,playing=false,lastTime=0,credited=0;const audio=$('#audio');audio.volume=.65;
function save(){try{localStorage.setItem(KEY,JSON.stringify(state))}catch{toast('Salvataggio non disponibile: i progressi dureranno solo in questa sessione.')}}
function round(){const day=rome().day;if(!state.rounds[day]){const ids=selectTracks(catalog,state.prefs,day+state.uid);state.rounds[day]={ids,listened:[],vote:null,day};save()}return state.rounds[day]}
function revealed(){return demoReveal||rome().revealed}function toast(s){$('#toast').textContent=s;$('#toast').style.display='block';setTimeout(()=>$('#toast').style.display='none',3800)}
const paths={daily:'<rect x="3" y="3" width="7" height="7" rx="2"/><rect x="14" y="3" width="7" height="7" rx="2"/><rect x="3" y="14" width="7" height="7" rx="2"/><rect x="14" y="14" width="7" height="7" rx="2"/>',ranks:'<path d="M5 20V12M12 20V4M19 20V8"/>',artist:'<path d="M9 18V5l12-2v13M9 7l12-2"/><ellipse cx="6" cy="18" rx="3" ry="3"/><ellipse cx="18" cy="16" rx="3" ry="3"/>',profile:'<circle cx="12" cy="8" r="4"/><path d="M4 22v-3a8 8 0 0 1 16 0v3"/>',play:'<path d="m9 5 11 7-11 7z" fill="currentColor"/>',pause:'<path d="M8 5v14M16 5v14" stroke-width="4"/>',check:'<path d="m5 12 4 4L19 6"/>'};
function icon(n){return`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${paths[n]||paths.play}</svg>`}function brand(){return'<div class="brand"><span class="logo"><i></i><i></i><i></i></span>vibe<span>pulse</span></div>'}
function navigate(r){route=r;location.hash=r;render();window.scrollTo(0,0)}window.addEventListener('hashchange',()=>{route=location.hash.slice(1)||'daily';render()});
function onboard(){return`<div class="onboarding"><section class="visual"><img src="art.png" alt="Scultura sonora cromata con riflessi viola e lime">${brand()}<h1>Prima la musica.<br><span class="lime">Poi il nome.</span></h1><div class="bottom"><span class="eyebrow">IL TUO NUOVO RITUALE</span><p>5 brani. Un voto. Ogni giorno.</p></div></section><section class="onboardform"><span class="eyebrow lime">${step+1} / 3 — ${['BENVENUTO NEL PULSE','LA TUA CONNESSIONE','I TUOI GUSTI'][step]}</span>${step===0?`<h1>La prossima scoperta<br>inizia da te.</h1><p>Ascolta cinque artisti emergenti, senza nome né numeri. Scegli chi ti fa sentire qualcosa.</p><div class="steps"><div class="step"><span class="num">01</span><b>Ascolta</b>5 estratti al buio</div><div class="step"><span class="num">02</span><b>Vota</b>Un solo preferito</div><div class="step"><span class="num">03</span><b>Scopri</b>Reveal alle 21:00</div></div><button class="btn" data-action="next">Entra nel pulse →</button>`:step===1?`<h1>Porta i tuoi gusti.<br>Scopri nuove voci.</h1><p>Spotify ci aiuterà a conoscere il tuo mondo musicale.</p><div class="notice">Stai provando una demo: nessun accesso al tuo account e nessuna password richiesta.</div><button class="btn" data-action="connect">Collega Spotify · simulazione</button><button class="textbtn" style="margin-top:20px" data-action="skip">Continua senza collegamento</button>`:`<h1>Che musica senti tua?</h1><p>Scegli almeno un genere. La selezione di oggi partirà da qui.</p><label>Come ti chiami?<input id="username" maxlength="35" placeholder="Il tuo nome" value="${escape(state.name)}" autocomplete="given-name"></label><div class="chips">${genres.map(g=>`<button class="chip ${pendingPrefs.includes(g)?'selected':''}" data-pref="${g}" aria-pressed="${pendingPrefs.includes(g)}">${g}</button>`).join('')}</div><button class="btn" data-action="finish" ${pendingPrefs.length?'':'disabled'}>Scopri i tuoi 5 brani →</button>`}<p class="hint" style="margin-top:25px">Artisti e audio dimostrativi · Gratuito, per tutti.</p></section></div>`}
function shell(content){return`<aside class="sidebar">${brand()}<nav class="nav" aria-label="Navigazione principale">${[['daily','Daily pulse'],['ranks','Classifiche'],['artist','Per gli artisti'],['profile','Il tuo profilo']].map(([id,label])=>`<button class="${route===id?'active':''}" data-nav="${id}" ${route===id?'aria-current="page"':''}>${icon(id)}${label}</button>`).join('')}</nav><div class="sidefoot"><div class="minicard"><span class="lime">La tua musica merita ascolto.</span><p>Meno di 10.000 ascoltatori? Questo è il tuo spazio.</p><button class="textbtn" data-nav="artist">Candida un brano ↗</button></div><div class="user"><div class="avatar">${escape((state.name||'Tu').slice(0,1).toUpperCase())}</div><div style="font-size:14px">${escape(state.name||'Ascoltatore')}<br><span class="muted" style="font-size:12px">${state.connected?'Spotify demo collegato':'Profilo demo'}</span></div></div></div></aside><main class="main"><header class="topbar"><span>La scoperta inizia dall’ascolto.</span><div class="mobilebrand">${brand()}</div><div class="topright"><span class="badge">DEMO INTERATTIVA</span><button class="avatar" data-nav="profile" aria-label="Apri profilo">${escape((state.name||'Tu')[0].toUpperCase())}</button></div></header>${content}<p class="footerline">VIBE PULSE © 2026 · Artisti, estratti e risultati dimostrativi · Orario Europe/Rome</p></main>${player()}`}
function daily(){const r=round(),reveal=revealed();return`<div class="heading"><div><h1>Il tuo daily pulse<span class="lime">.</span></h1><p>${new Intl.DateTimeFormat('it-IT',{weekday:'long',day:'numeric',month:'long',timeZone:'Europe/Rome'}).format(new Date())} · Una nuova selezione, ogni giorno.</p></div><span class="badge">5 BRANI / 1 VOTO</span></div>${demoReveal?'<div class="notice">Stai vedendo il reveal di prova. <button class="textbtn" data-action="reveal">Torna al contest</button></div>':''}<section class="hero"><img src="art.png" alt="Onda sonora cromata viola e lime"><div class="copy"><span class="eyebrow">${reveal?'IL MOMENTO DEL REVEAL':'ASCOLTA OLTRE IL NOME'}</span><h2>${reveal?'Le voci hanno<br>finalmente un nome.':'Non sai chi è.<br>Ma sai cosa senti.'}</h2><p>${reveal?'Scopri tutti gli artisti della tua selezione. Il tuo prossimo preferito potrebbe essere qui.':'Cinque estratti scelti per te. Ascoltali tutti e lascia che sia la musica a decidere.'}</p></div><div class="countdown"><small>${reveal?'REVEAL APERTO':'REVEAL ALLE 21:00'}</small><strong id="countdown">${reveal?'21:00':countdown()}</strong></div></section>${r.vote?`<div class="success revealbanner" style="margin-top:20px"><div class="row"><div><b>✓ Il tuo voto è nel pulse.</b><div class="hint">Hai scelto il brano ${String(r.ids.indexOf(r.vote)+1).padStart(2,'0')}. ${reveal?'Scopri ora tutte le voci.':'Artisti e risultati saranno visibili alle 21:00.'}</div></div>${!reveal?'<button class="textbtn" data-action="reveal">Prova il reveal →</button>':''}</div></div>`:''}<div class="sectionhead"><h2>${reveal?'I tuoi artisti di oggi':'La tua selezione'}</h2><span class="progresslabel">${reveal?'Tutti meritano di essere scoperti':`${r.listened.length}/5 ascoltati · Estratti da 12 s`}</span></div><div class="tracks">${r.ids.map((id,i)=>card(catalog.find(t=>t.id===id),i)).join('')}</div><div class="bottomgrid"><section class="panel"><h3>Un piccolo rito. Nuove grandi scoperte.</h3><div class="steps"><div class="step"><span class="num">01</span><b>Premi play</b>Ascolta tutti i 5 estratti.</div><div class="step"><span class="num">02</span><b>Segui l’istinto</b>Il tuo voto è unico.</div><div class="step"><span class="num">03</span><b>Torna alle 21</b>Scopri chi ti ha colpito.</div></div></section><section class="panel"><span class="eyebrow lime">PIÙ SPAZIO A NUOVE VOCI</span><h3 style="margin-top:14px">I tuoi gusti. Le loro opportunità.</h3><p class="hint">Selezione casuale tra i generi che ami, con più probabilità per i brani meno esposti.</p><button class="textbtn" data-nav="ranks">Come funziona il ranking ↗</button>${!reveal?'<button class="textbtn" data-action="reveal" style="display:block;margin-top:14px;color:var(--muted)">Prova il reveal delle 21:00</button>':''}</section></div>`}
function card(t,i){const r=round(),rev=revealed(),heard=r.listened.includes(t.id);return`<article class="track ${active===t.id&&playing?'playing':''}"><div class="cover v${i}"><span class="number">${String(i+1).padStart(2,'0')}</span><button class="play" data-play="${t.id}" aria-label="${active===t.id&&playing?'Pausa':'Ascolta'} brano ${i+1}">${icon(active===t.id&&playing?'pause':'play')}</button></div><div class="trackmeta"><span>${t.genre}</span><span class="${heard?'check':''}">${heard?'✓ Ascoltato':'12 sec'}</span></div><h3>${rev?escape(t.title):`Brano ${String(i+1).padStart(2,'0')}`}</h3><p>${rev?escape(t.artist):`${t.mood} · ${t.lang}`}</p>${rev?`<button class="vote ${state.saved.includes(t.id)?'chosen':''}" data-save="${t.id}">${state.saved.includes(t.id)?'✓ Salvato':'＋ Salva scoperta'}</button><a class="textbtn" style="display:block;margin-top:10px;font-size:12px" href="https://open.spotify.com/search/${encodeURIComponent(t.genre)}" target="_blank" rel="noopener">Esplora ${t.genre} su Spotify ↗</a>`:`<button class="vote ${r.vote===t.id?'chosen':''}" data-vote="${t.id}" ${!canVote(r,rev)?'disabled':''}>${r.vote===t.id?'✓ Il tuo voto':r.vote?'Voto concluso':r.listened.length<5?'Ascolta tutti per votare':'Vota questo brano'}</button>`}</article>`}
function countdown(){const left=Math.max(0,21*3600-rome().seconds);return[Math.floor(left/3600),Math.floor(left/60)%60,left%60].map(n=>String(n).padStart(2,'0')).join(':')}
function player(){const t=catalog.find(t=>t.id===active),index=round().ids.indexOf(active);return`<section class="player" aria-label="Player musicale"><div class="playerinfo"><strong>${t?(revealed()?escape(t.title):`Brano ${String(index+1).padStart(2,'0')}`):'Pronto a scoprire?'}</strong><span>${t?`${t.genre} · Audio demo`:'Premi play su un estratto'}</span></div><button data-action="playcurrent" aria-label="${playing?'Pausa':'Riproduci'}">${icon(playing?'pause':'play')}</button><progress id="playprogress" value="${audio.currentTime||0}" max="12" aria-label="Avanzamento estratto"></progress><span class="time" id="playtime">${Math.floor(audio.currentTime||0)} / 12 s</span><label>Volume<input id="volume" type="range" min="0" max="1" step="0.05" value="${audio.volume}"></label></section>`}
function ranks(){const today=rome().day,closed=revealed();let d=new Date(`${today}T12:00:00Z`);if(period==='day'&&!closed)d.setUTCDate(d.getUTCDate()-1);if(period==='week'){const since=d.getUTCDay();d.setUTCDate(d.getUTCDate()-(since===0?(closed?0:7):since));}const reference=d.toISOString().slice(0,10);let ranked=rankRows(catalog,period,reference);if(period==='day'&&reference===today&&closed){const r=round();ranked=ranked.map(t=>{const exposures=t.exposures+(r.ids.includes(t.id)?1:0),votes=t.votes+(r.vote===t.id?1:0);return{...t,exposures,votes,score:score(votes,exposures)}}).sort((a,b)=>b.score-a.score);}const rows=ranked.filter(t=>filter==='Tutti'||t.genre===filter);return`<div class="heading"><div><h1>La musica sale<span class="lime">.</span></h1><p>Le classifiche di chi si è fatto sentire.</p></div><span class="badge">DATI DEMO</span></div><div class="ranktabs" role="group" aria-label="Periodo classifica"><button data-period="day" class="${period==='day'?'active':''}">Giornaliera</button><button data-period="week" class="${period==='week'?'active':''}">Settimanale</button></div><div class="row"><div class="chips">${['Tutti',...genres].map(g=>`<button class="chip ${filter===g?'selected':''}" data-filter="${g}" aria-pressed="${filter===g}">${g}</button>`).join('')}</div><span class="hint">${period==='week'?'Settimana conclusa il':'Contest del'} ${reference.split('-').reverse().join('/')}</span></div><div class="panel" style="margin:0 0 22px"><h3>Conta la risposta, non la notorietà.</h3><p class="hint" style="margin-bottom:0">Punteggio = voti ÷ esposizioni × 100. 120 voti su 400 esposizioni valgono il 30%. Le posizioni vengono confrontate all’interno di ogni genere. La settimanale somma voti ed esposizioni dei sette giorni e si chiude domenica alle 21:00.</p></div>${filter==='Tutti'?genres.map(g=>rankBlock(rows.filter(t=>t.genre===g),g)).join(''):rankBlock(rows,filter)}`}
function rankBlock(rows,g){return`<h2 style="font-size:20px;margin:24px 0 14px">${g}</h2><div class="ranklist">${rows.map((t,i)=>`<div class="rankrow"><span class="position">${String(i+1).padStart(2,'0')}</span><div><strong>${escape(t.title)}</strong><br><small>${escape(t.artist)}</small></div><div class="metrics"><small>${t.votes} voti<br>${t.exposures} esposizioni</small></div><span class="score">${(t.score*100).toFixed(1).replace('.',',')}<small>%</small></span></div>`).join('')}</div>`}
function artist(){return`<div class="heading"><div><h1>Fatti sentire<span class="lime">.</span></h1><p>Il prossimo brano che lascia il segno potrebbe essere il tuo.</p></div></div><div class="formwrap"><div class="panel" style="margin-bottom:22px"><span class="eyebrow lime">IL TALENTO PRIMA DEI NUMERI</span><h2>Un posto per chi sta iniziando.</h2><p class="hint">Candidatura gratuita per artisti con meno di 10.000 ascoltatori mensili. Nessuna posizione a pagamento.</p></div><form id="artistform" class="panel"><div class="formgrid"><label>Nome artista<input name="artist" required maxlength="70" placeholder="Il tuo nome d’arte"></label><label>Titolo del brano<input name="title" required maxlength="100" placeholder="Come si chiama il brano?"></label><label>Ascoltatori mensili su Spotify<input name="listeners" type="number" min="0" max="9999" step="1" required placeholder="Es. 2500"></label><label>Genere<select name="genre">${genres.map(g=>`<option>${g}</option>`).join('')}</select></label><label>Lingua<select name="language"><option>Italiano</option><option>Inglese</option><option>Spagnolo</option><option>Francese</option><option>Altra</option><option>Strumentale</option></select></label><label>Sottogenere<input name="subgenre" required maxlength="60" placeholder="Es. Bedroom pop"></label><label>Mood<select name="mood"><option>Sognante</option><option>Energico</option><option>Notturno</option><option>Malinconico</option><option>Euforico</option><option>Intimo</option></select></label><label>Link del brano su Spotify<input name="spotify" type="url" required placeholder="https://open.spotify.com/track/…"></label><label class="full"><input name="rights" type="checkbox" required> Confermo di avere i diritti per candidare il brano e autorizzarne l’estratto.</label><p class="hint full" style="margin:0">Modalità demo: candidatura salvata solo su questo browser. Il numero di ascoltatori è autodichiarato; non viene interrogata Spotify.</p><p class="error full" id="formerror" role="alert" style="margin:0"></p><button class="btn full" type="submit">Invia candidatura →</button></div></form>${state.applications.length?`<h2>Le tue candidature demo</h2>${state.applications.map(a=>`<div class="panel" style="margin-top:10px"><b>${escape(a.title)}</b> · ${escape(a.artist)}<p class="hint">${escape(a.genre)} · ${escape(a.mood)} · Da verificare prima della selezione</p></div>`).join('')}`:''}</div>`}
function profile(){const rounds=Object.values(state.rounds),votes=rounds.filter(r=>r.vote);return`<div class="heading"><div><h1>Il tuo spazio<span class="lime">.</span></h1><p>Le tue scelte danno spazio a nuove voci.</p></div></div><div class="panel"><div class="row"><div class="user"><div class="avatar" style="width:56px;height:56px;font-size:24px">${escape((state.name||'Tu')[0].toUpperCase())}</div><div><h3>${escape(state.name||'Ascoltatore')}</h3><span class="hint">${state.connected?'Spotify collegato · simulazione':'Spotify non collegato'}</span></div></div><button class="btn secondary small" data-action="toggleSpotify">${state.connected?'Scollega':'Collega Spotify demo'}</button></div></div><div class="statgrid"><div class="panel"><strong>${votes.length}</strong><small>Voti espressi</small></div><div class="panel"><strong>${rounds.reduce((n,r)=>n+r.listened.length,0)}</strong><small>Brani ascoltati</small></div><div class="panel"><strong>${state.saved.length}</strong><small>Scoperte salvate</small></div></div><div class="panel"><h3>I tuoi gusti, la tua selezione</h3><p class="hint">I cambiamenti valgono dalla selezione di domani.</p><form id="profileform"><label>Nome<input name="name" maxlength="35" value="${escape(state.name)}"></label><div class="chips">${genres.map(g=>`<label class="chip"><input type="checkbox" name="genre" value="${g}" ${state.prefs.includes(g)?'checked':''}>${g}</label>`).join('')}</div><button class="btn small">Salva preferenze</button><span id="profileerror" class="error" role="alert"></span></form></div><h2>Le tue scoperte</h2><div class="savedlist">${state.saved.length?state.saved.map(id=>{const t=catalog.find(t=>t.id===id);return`<div class="panel"><b>${escape(t.title)}</b><p class="hint">${escape(t.artist)} · ${t.genre}</p><button class="textbtn" data-save="${id}">Rimuovi dai salvati</button></div>`}).join(''):'<p>Le scoperte che salvi dopo il reveal appariranno qui.</p>'}</div><h2>Il tuo diario di ascolto</h2>${votes.length?votes.map(r=>`<div class="historyitem">${r.day} · Voto registrato per il brano ${r.ids.indexOf(r.vote)+1} · ${r.listened.length}/5 ascoltati</div>`).join(''):'<p>Il tuo primo voto è ancora da scrivere.</p>'}`}
function render(){if(!state.onboard){$('#app').innerHTML=onboard();return}if(!['daily','ranks','artist','profile'].includes(route))route='daily';$('#app').innerHTML=shell(({daily,ranks,artist,profile}[route])());}
async function play(id){if(active===id&&playing){audio.pause();return}if(active!==id){audio.pause();active=id;audio.src=`audio/${round().ids.indexOf(id)}.wav`;lastTime=0;credited=0;}try{await audio.play()}catch{toast('Audio non disponibile. Riprova a premere play.')}render()}
audio.addEventListener('play',()=>{playing=true;render()});audio.addEventListener('pause',()=>{playing=false;render()});audio.addEventListener('timeupdate',()=>{const dt=audio.currentTime-lastTime;if(dt>0&&dt<1.5)credited+=dt;lastTime=audio.currentTime;if($('#playprogress'))$('#playprogress').value=audio.currentTime;if($('#playtime'))$('#playtime').textContent=`${Math.floor(audio.currentTime)} / 12 s`;});audio.addEventListener('ended',()=>{if(credited>=10.5&&!round().listened.includes(active)){round().listened.push(active);save();toast(round().listened.length===5?'5 su 5. Ora puoi scegliere il tuo preferito.':'Ascolto completato ✓')}credited=0;lastTime=0;playing=false;render()});audio.addEventListener('error',()=>{if(active)toast('Impossibile caricare l’audio demo.')});
function modal(html){$('#modal').innerHTML=html;$('#modal').showModal()}function confirmVote(id){if(!canVote(round(),revealed()))return;const n=round().ids.indexOf(id)+1;modal(`<span class="eyebrow lime">LA TUA SCELTA CONTA</span><h2>Il brano ${String(n).padStart(2,'0')} è il tuo preferito?</h2><p>Hai un solo voto al giorno. Una volta confermato, non potrai cambiarlo.</p><div class="actions"><button class="btn secondary" data-action="close">Ci ripenso</button><button class="btn" data-confirm="${id}">Conferma voto</button></div>`)}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.nav)return navigate(b.dataset.nav);if(b.dataset.play)return play(b.dataset.play);if(b.dataset.vote)return confirmVote(b.dataset.vote);if(b.dataset.confirm){let latest;try{latest=JSON.parse(localStorage.getItem(KEY))}catch{}if(latest?.rounds?.[rome().day]?.vote){state=latest;$('#modal').close();render();return toast('Hai già votato oggi.')}if(!canVote(round(),revealed())){$('#modal').close();return toast('Il voto non è più disponibile.')}round().vote=b.dataset.confirm;save();$('#modal').close();render();modal('<span class="eyebrow lime">VOTO REGISTRATO</span><h2>Hai dato voce<br>a una nuova scoperta.</h2><p>Grazie per aver ascoltato prima di giudicare. Torna alle 21:00 per scoprire tutti gli artisti.</p><div class="actions"><button class="btn" data-action="close">Torna al pulse</button></div>');return}if(b.dataset.save){const id=b.dataset.save;state.saved=state.saved.includes(id)?state.saved.filter(x=>x!==id):[...state.saved,id];save();render();return}if(b.dataset.pref){const g=b.dataset.pref;state.name=$('#username')?.value||state.name;pendingPrefs=pendingPrefs.includes(g)?pendingPrefs.filter(x=>x!==g):[...pendingPrefs,g];render();return}if(b.dataset.period){period=b.dataset.period;render();return}if(b.dataset.filter){filter=b.dataset.filter;render();return}switch(b.dataset.action){case'next':step++;render();break;case'connect':state.connected=true;step=2;render();break;case'skip':step=2;render();break;case'finish':if(!pendingPrefs.length)return;state.name=$('#username').value.trim()||'Ascoltatore';state.prefs=pendingPrefs;state.onboard=true;save();render();window.scrollTo(0,0);break;case'close':$('#modal').close();break;case'reveal':demoReveal=!demoReveal;render();break;case'playcurrent':play(active||round().ids[0]);break;case'toggleSpotify':state.connected=!state.connected;save();render();toast(state.connected?'Collegamento demo attivo.':'Collegamento demo rimosso.');break;}});
document.addEventListener('input',e=>{if(e.target.id==='volume')audio.volume=+e.target.value});
document.addEventListener('submit',e=>{if(e.target.id==='profileform'){e.preventDefault();const fd=new FormData(e.target),prefs=fd.getAll('genre');if(!prefs.length){$('#profileerror').textContent=' Scegli almeno un genere.';return}state.name=String(fd.get('name')).trim()||'Ascoltatore';state.prefs=prefs;save();render();toast('Preferenze salvate per domani.')}if(e.target.id==='artistform'){e.preventDefault();const fd=new FormData(e.target),data=Object.fromEntries(fd),n=Number(data.listeners);if(!eligibility(n)){$('#formerror').textContent='Sono ammessi solo valori interi da 0 a 9.999 ascoltatori mensili.';return}let u;try{u=new URL(data.spotify)}catch{}if(!u||u.protocol!=='https:'||u.hostname!=='open.spotify.com'||!/^\/(?:intl-[a-z]{2}\/)?track\/[a-zA-Z0-9]{22}\/?$/.test(u.pathname)){$('#formerror').textContent='Inserisci un link Spotify valido a un brano (open.spotify.com/track/…).';return}if(state.applications.some(a=>new URL(a.spotify).pathname===u.pathname)){$('#formerror').textContent='Hai già candidato questo brano.';return}state.applications.push({...data,listeners:n,id:crypto.randomUUID(),created:new Date().toISOString()});save();render();modal('<span class="eyebrow lime">CANDIDATURA DEMO SALVATA</span><h2>Il primo passo<br>è farsi sentire.</h2><p>Trovi il brano nelle tue candidature. Questa simulazione non invia dati a un team: il brano resta in attesa di verifica e non entra automaticamente nel contest.</p><button class="btn" data-action="close">Perfetto</button>')}});
let previousDay=rome().day,previousReveal=rome().revealed;setInterval(()=>{const now=rome();if(now.day!==previousDay||now.revealed!==previousReveal){previousDay=now.day;previousReveal=now.revealed;demoReveal=false;audio.pause();active=null;round();render()}else if($('#countdown')&&!revealed())$('#countdown').textContent=countdown()},1000);window.addEventListener('storage',e=>{if(e.key===KEY&&e.newValue){try{state=JSON.parse(e.newValue);render()}catch{}}});render();
